import Menu from "./menu";

interface RecentItem {
    title: string;
    url: string;
}

const RECENT_STORAGE_KEY = "gs-recently-viewed";
const RECENT_MAX = 5;
const LOCALE_SEED_TIMEOUT_MS = 8000;

class Search {
    private _header: HTMLElement;
    private _headerTop: HTMLElement;
    private _searchWrap: HTMLElement;
    private _panel: HTMLElement;
    private _backdrop: HTMLElement;
    private _recentList: HTMLElement;
    private _clearFiltersBtn: HTMLButtonElement;
    private _escHint: HTMLButtonElement;
    private _input: HTMLInputElement | null;

    private _isOpen: boolean;
    private _hasSeededLocale: boolean;

    init() {
        this._header = document.querySelector("#site-header");
        if (!this._header) {
            return;
        }

        this._headerTop = this._header.querySelector(".header-top");
        this._searchWrap = this._header.querySelector("#search-wrap");
        this._panel = this._header.querySelector("#search-panel");
        this._backdrop = document.querySelector("#search-backdrop");
        this._recentList = document.querySelector("#search-recent-list");
        this._clearFiltersBtn = document.querySelector("#search-clear-filters");
        this._escHint = document.querySelector("#search-esc-hint");

        if (!this._headerTop || !this._panel || !this._backdrop) {
            return;
        }

        this._isOpen = false;
        this._hasSeededLocale = false;

        // A review page visiting itself writes to "recently viewed" on
        // load, independent of whether search is ever opened this visit —
        // the panel just reads whatever's accumulated so far.
        this.recordRecentlyViewed();
        this.renderRecentlyViewed();

        // .header-top's own height changes across breakpoints (mobile wraps
        // the search field to its own row below the logo) and can change at
        // runtime (font loading, window resize) — ResizeObserver keeps the
        // panel's offset correct rather than baking in one breakpoint's
        // measurement.
        new ResizeObserver(() => this.syncPanelOffset()).observe(this._headerTop);
        this.syncPanelOffset();

        this.bindInput();

        document.addEventListener("keydown", (e) => this.handleKeydown(e));
        this._backdrop.addEventListener("click", () => this.close());
        this._escHint?.addEventListener("click", () => this.close());
        this._clearFiltersBtn?.addEventListener("click", () => this.clearFilters());

        // Any other header trigger (locale switcher, hamburger, a mega-menu
        // tab) closes search first — the mirror image of Menu's own
        // mutual-exclusion pass over its three panels, so search doesn't end
        // up trapped open underneath one of them.
        document
            .querySelectorAll(".locale-switch-trigger, #m-menu-trigger, .facet-tab.has-mega")
            .forEach((trigger) => trigger.addEventListener("click", () => this.close()));
    }

    // .search-panel is positioned absolutely within #site-header (a sibling
    // of .header-top, not nested inside the input's own flex column — see
    // body-header.html) so it can be wide/centered independent of the
    // input's own width. Deliberately biasing 1px into overlap (floor, then
    // one more px) rather than rounding guarantees the panel's top edge
    // always sits a hair under .header-top's own box regardless of which
    // way the true fractional height would round — search.scss gives
    // .header-top a higher z-index than the panel/backdrop specifically so
    // that overlap is invisible rather than needing pixel-perfect alignment.
    private syncPanelOffset() {
        if (!this._headerTop || !this._panel) {
            return;
        }

        const height = this._headerTop.getBoundingClientRect().height;
        this._panel.style.top = `${Math.floor(height) - 1}px`;
    }

    // <pagefind-input> renders its own native <input> into the light DOM
    // once the pagefind-component-ui.js module upgrades the element — which
    // in practice has already happened by the time this runs (that script
    // is declared in <head> and executes, in document order, before our own
    // deferred bundle script). The MutationObserver fallback only matters if
    // that ordering ever changes.
    private bindInput() {
        // pagefind-input lives in #search-wrap, inside .header-top — a
        // sibling of #search-panel, not a descendant of it.
        const tryBind = (): boolean => {
            const input = this._header.querySelector<HTMLInputElement>("pagefind-input input");
            if (!input) {
                return false;
            }

            this._input = input;
            input.addEventListener("focus", () => this.open());
            input.addEventListener("input", () => this.syncQueryState());
            this.syncQueryState();
            return true;
        };

        if (tryBind()) {
            return;
        }

        const observer = new MutationObserver(() => {
            if (tryBind()) {
                observer.disconnect();
            }
        });
        observer.observe(this._header, { childList: true, subtree: true });
    }

    // The panel must fully hide the summary/filter/results columns on an
    // empty query rather than show them with a stale count or nothing in
    // them — data-query drives that in search.scss.
    private syncQueryState() {
        if (!this._input || !this._panel) {
            return;
        }

        const hasQuery = !!this._input.value.trim();
        this._panel.dataset.query = hasQuery ? "active" : "empty";
        this._searchWrap?.classList.toggle("has-query", hasQuery);
    }

    open() {
        if (this._isOpen) {
            return;
        }

        this._isOpen = true;
        Menu.closeLocalePanel();
        Menu.closeMobileMenu();
        Menu.closeMegaMenus();
        this._header.classList.add("search-open");
        // Rows inside the panel above the results (summary, filter chips)
        // aren't themselves scrollable, so a wheel/touch scroll there was
        // falling through to the dimmed page underneath rather than doing
        // nothing — locking body scroll while the panel's open stops that
        // without affecting the panel's own scrollable regions (filter
        // pane, results), which keep their own overflow: auto regardless.
        document.body.classList.add("search-scroll-lock");
        this.renderRecentlyViewed();
        this.seedLocaleFilter();
    }

    close() {
        if (!this._isOpen) {
            return;
        }

        this._isOpen = false;
        this._header.classList.remove("search-open");
        document.body.classList.remove("search-scroll-lock");
        this._input?.blur();
    }

    // Scoped to the search field + panel specifically, not the whole
    // header — Stats/Map/RSS/the locale switcher all live inside #site-
    // header too, so checking against the whole header treated clicking
    // any of them as an "inside" click and never closed the panel.
    handleOutsideClick(target: Node) {
        if (!this._isOpen) {
            return;
        }

        const insideSearch =
            (this._searchWrap && this._searchWrap.contains(target)) || (this._panel && this._panel.contains(target));

        if (!insideSearch) {
            this.close();
        }
    }

    private handleKeydown(e: KeyboardEvent) {
        if (e.key === "Escape") {
            if (this._isOpen) {
                this.close();
            }
            return;
        }

        if (e.key !== "/" || this._isOpen) {
            return;
        }

        // Don't hijack "/" while the user is typing into some other field.
        const target = e.target as HTMLElement | null;
        const tag = target?.tagName;
        if (tag === "INPUT" || tag === "TEXTAREA" || target?.isContentEditable) {
            return;
        }

        e.preventDefault();
        this._input?.focus();
    }

    // Pagefind's filter-pane component doesn't document an attribute for
    // pre-selecting a value on load, so this drives it the same way a user
    // would: find the rendered checkbox whose label matches the current
    // locale and click it for real. Runs once per page (guarded), retried
    // via MutationObserver since the filter-pane's options only populate
    // once Pagefind's index bundle finishes loading.
    private seedLocaleFilter() {
        if (this._hasSeededLocale) {
            return;
        }

        const localeName = this._panel.dataset.seedLocale;
        if (!localeName) {
            this._hasSeededLocale = true;
            return;
        }

        const pane = this._panel.querySelector<HTMLElement>(".search-filter-pane");
        if (!pane) {
            this._hasSeededLocale = true;
            return;
        }

        // Scoped to input[name="locale"] specifically (not every checkbox
        // in the pane) and matched by exact value (not a label-text prefix
        // match) — confirmed live that the old prefix match on "Hawaii"
        // matched the Cuisine option "Hawaiian" before it ever found the
        // real (hidden) Locale option "Hawaii", silently seeding the wrong
        // filter. Every checkbox's real value attribute holds the exact
        // facet value pagefind indexed, so an exact compare against that —
        // scoped to the one group that can't collide with another facet's
        // values — can't misfire the way a fuzzy text match across the
        // whole pane could.
        const tryClick = (): boolean => {
            const checkboxes = Array.from(pane.querySelectorAll<HTMLInputElement>('input[name="locale"]'));
            const match = checkboxes.find((cb) => cb.value.trim().toLowerCase() === localeName.toLowerCase());

            if (!match) {
                return false;
            }

            if (!match.checked) {
                match.click();
            }

            return true;
        };

        if (tryClick()) {
            this._hasSeededLocale = true;
            return;
        }

        const observer = new MutationObserver(() => {
            if (tryClick()) {
                this._hasSeededLocale = true;
                observer.disconnect();
            }
        });
        observer.observe(pane, { childList: true, subtree: true });

        window.setTimeout(() => {
            observer.disconnect();
            this._hasSeededLocale = true;
        }, LOCALE_SEED_TIMEOUT_MS);
    }

    // Real checkbox clicks (rather than any undocumented internal API) so
    // this keeps working regardless of how pagefind-filter-pane wires its
    // own state internally — same reasoning as seedLocaleFilter above.
    private clearFilters() {
        const pane = this._panel?.querySelector(".search-filter-pane");
        const isScoped = !!this._panel?.dataset.seedLocale;

        pane?.querySelectorAll<HTMLInputElement>('input[type="checkbox"]:checked').forEach((cb) => {
            // On a scoped page the seeded Locale checkbox is hidden (see
            // search.scss) and isn't a user-added filter — clearing it
            // would silently broaden results to every locale with no
            // visible control left to undo that.
            if (isScoped && cb.name === "locale") {
                return;
            }

            cb.checked = false;
            cb.dispatchEvent(new Event("change", { bubbles: true }));
        });
    }

    private readRecentItems(): RecentItem[] {
        try {
            const raw = localStorage.getItem(RECENT_STORAGE_KEY);
            const items = raw ? JSON.parse(raw) : [];
            return Array.isArray(items) ? items : [];
        } catch {
            return [];
        }
    }

    private recordRecentlyViewed() {
        const heroTitle = document.querySelector<HTMLElement>("article[data-pagefind-body] .hero-info h1");
        const title = heroTitle?.textContent?.trim();
        if (!title) {
            return;
        }

        const url = window.location.pathname;
        const items = this.readRecentItems().filter((item) => item.url !== url);
        items.unshift({ title, url });

        try {
            localStorage.setItem(RECENT_STORAGE_KEY, JSON.stringify(items.slice(0, RECENT_MAX)));
        } catch {
            // localStorage unavailable (private browsing, quota) — recently
            // viewed just won't persist this session, nothing else depends on it.
        }
    }

    private renderRecentlyViewed() {
        if (!this._recentList) {
            return;
        }

        // Excludes the current page, same convention as the sidebar's own
        // "Latest" module — visiting a review shouldn't list itself.
        const items = this.readRecentItems().filter((item) => item.url !== window.location.pathname);

        if (!items.length) {
            this._recentList.innerHTML = '<div class="search-recent-empty">No recently viewed reviews yet.</div>';
            return;
        }

        this._recentList.innerHTML = "";
        items.forEach((item) => {
            const a = document.createElement("a");
            a.className = "search-recent-item";
            a.href = item.url;
            a.textContent = item.title;
            this._recentList.appendChild(a);
        });
    }
}

export default new Search();
