import { Observable, fromEvent, merge } from "rxjs";

class Menu {
    private _localeTriggers: NodeListOf<HTMLElement>;
    private _localePanel: HTMLDivElement;
    private _mobileMenuTrigger: HTMLSpanElement;
    private _mobileMenuPanel: HTMLDivElement;
    private _megaTabs: NodeListOf<HTMLElement>;

    private _isLocalePanelVisible: boolean;
    private _isMobileMenuVisible: boolean;
    private _openMegaTab: HTMLElement | null;

    private mobileMenuTriggerObservable$: Observable<Event>;

    init() {
        // Multiple entry points open the same shared panel: the desktop
        // header button, the homepage's mobile "All Locales" pill, and the
        // mobile-only caret next to "All {locale}" on locale/term pages.
        this._localeTriggers = document.querySelectorAll(".locale-switch-trigger");
        this._localePanel = document.querySelector("#locale-panel");

        if (this._localeTriggers.length && this._localePanel) {
            let localeTriggerObservable$: Observable<Event> | null = null;

            this._localeTriggers.forEach((trigger) => {
                const click$ = fromEvent(trigger, "click");
                localeTriggerObservable$ = localeTriggerObservable$ ? merge(localeTriggerObservable$, click$) : click$;
            });

            localeTriggerObservable$.subscribe((e) => this.toggleLocalePanel(e));
        }

        this._mobileMenuTrigger = document.querySelector("#m-menu-trigger");
        this._mobileMenuPanel = document.querySelector("#m-menu-panel");

        if (this._mobileMenuTrigger && this._mobileMenuPanel) {
            this.mobileMenuTriggerObservable$ = fromEvent(this._mobileMenuTrigger, "click");
            this.mobileMenuTriggerObservable$.subscribe((e) => this.toggleMobileMenu(e));
        }

        this._megaTabs = document.querySelectorAll(".facet-tab.has-mega");
        this._megaTabs.forEach((tab) => {
            tab.addEventListener("click", (e) => this.toggleMegaMenu(e, tab));
        });
    }

    // The locale panel, mobile hamburger menu, and mega-menus are mutually
    // exclusive — opening any one closes the other two first. Without this,
    // e.g. opening "Areas" while the locale panel is already open leaves
    // both in the DOM at once, and since .locale-panel has a higher z-index
    // than .mega, the mega-menu renders visually stuck underneath it.
    toggleLocalePanel(e?: Event) {
        if (e) {
            e.preventDefault();
            e.stopPropagation();
        }

        if (this._isLocalePanelVisible) {
            this.closeLocalePanel();
        } else {
            this.closeMegaMenus();
            this.closeMobileMenu();
            this._isLocalePanelVisible = true;
            if (e?.currentTarget instanceof HTMLElement) {
                this.positionLocalePanel(e.currentTarget);
            }
            this._localePanel.classList.add("open");
            this._localeTriggers.forEach((trigger) => trigger.setAttribute("aria-expanded", "true"));
        }
    }

    // .locale-panel is a direct child of header.site rather than of whichever
    // trigger opened it (see the comment on _localeTriggers above), so unlike
    // .mega — which is a child of its own .facet-tab and sits flush beneath
    // it for free — its "top: 100%" CSS default measures from the bottom of
    // the entire multi-row header, not the trigger's own row. That leaves it
    // floating well below the clicked trigger with a large gap. Position it
    // explicitly from the trigger's actual rect instead.
    positionLocalePanel(trigger: HTMLElement) {
        const header = this._localePanel.parentElement;
        if (!header) {
            return;
        }

        const headerRect = header.getBoundingClientRect();
        const triggerRect = trigger.getBoundingClientRect();

        this._localePanel.style.top = `${triggerRect.bottom - headerRect.top + 8}px`;

        // Below 700px the panel spans the full header width (left/right: 0
        // in CSS) regardless of the trigger's position, so leave left alone
        // there — an inline style would otherwise win over that media query.
        if (window.matchMedia("(min-width: 43.75rem)").matches) {
            this._localePanel.style.left = `${triggerRect.left - headerRect.left}px`;
        } else {
            this._localePanel.style.left = "";
        }
    }

    closeLocalePanel() {
        if (!this._isLocalePanelVisible) {
            return;
        }

        this._isLocalePanelVisible = false;
        this._localePanel.classList.remove("open");
        this._localeTriggers.forEach((trigger) => trigger.setAttribute("aria-expanded", "false"));
    }

    toggleMobileMenu(e?: Event) {
        if (e) {
            e.preventDefault();
            e.stopPropagation();
        }

        if (this._isMobileMenuVisible) {
            this.closeMobileMenu();
        } else {
            this.closeLocalePanel();
            this.closeMegaMenus();
            this._isMobileMenuVisible = true;
            this._mobileMenuPanel.classList.add("open");
            this._mobileMenuTrigger.setAttribute("aria-expanded", "true");
        }
    }

    closeMobileMenu() {
        if (!this._isMobileMenuVisible) {
            return;
        }

        this._isMobileMenuVisible = false;
        this._mobileMenuPanel.classList.remove("open");
        this._mobileMenuTrigger.setAttribute("aria-expanded", "false");
    }

    toggleMegaMenu(e: Event, tab: HTMLElement) {
        const target = e.target as HTMLElement;
        const mega = tab.querySelector(".mega");

        // The dropdown is a child of the tab, so clicks on its real links
        // bubble through this same listener — let those navigate normally
        // instead of toggling (and hiding) the menu out from under them.
        if (mega && mega.contains(target)) {
            return;
        }

        e.preventDefault();
        e.stopPropagation();

        const alreadyOpen = this._openMegaTab === tab;

        this.closeMegaMenus();

        if (!alreadyOpen) {
            this.closeLocalePanel();
            this.closeMobileMenu();
            tab.classList.add("open");
            this._openMegaTab = tab;
        }
    }

    closeMegaMenus() {
        this._megaTabs.forEach((tab) => tab.classList.remove("open"));
        this._openMegaTab = null;
    }

    // Closes open panels only when the click landed outside them — a click
    // on a real link *inside* an open panel must be left alone, otherwise
    // hiding the panel mid-click (display: none) cancels the link's default
    // navigation before the browser commits to it.
    handleOutsideClick(target: Node) {
        if (this._isLocalePanelVisible && this._localePanel && !this._localePanel.contains(target)) {
            this.closeLocalePanel();
        }

        if (
            this._isMobileMenuVisible &&
            this._mobileMenuTrigger &&
            !this._mobileMenuTrigger.contains(target) &&
            this._mobileMenuPanel &&
            !this._mobileMenuPanel.contains(target)
        ) {
            this.closeMobileMenu();
        }

        if (this._openMegaTab && !this._openMegaTab.contains(target)) {
            this.closeMegaMenus();
        }
    }
}

export default new Menu();
