import Menu from "./menu";
import Search from "./search";
import SidebarLatest from "./sidebar-latest";
import LoadMore from "./load-more";
import ScrollToTop from "./scroll-to-top";
import "normalize.css";
import "src/scss/index.scss"; /* eslint-disable-line */

(function () {
    Menu.init();
    Search.init();
    SidebarLatest.init();
    ScrollToTop.init();

    new LoadMore({ gridSelector: "#tile-grid", itemSelector: "a.tile", buttonSelector: "#load-more" }).init();
    new LoadMore({ gridSelector: "#feed", itemSelector: "div.card", buttonSelector: "#load-more-feed" }).init();

    window.addEventListener("click", function (event) {
        Menu.handleOutsideClick(event.target as Node);
        Search.handleOutsideClick(event.target as Node);
    });
})();
