const VISIBLE_AFTER_PX = 800;

class ScrollToTop {
    private _button: HTMLButtonElement;

    init() {
        this._button = document.querySelector("#scroll-to-top");

        if (!this._button) {
            return;
        }

        this._button.hidden = false;
        window.addEventListener("scroll", () => this.handleScroll(), { passive: true });
        this._button.addEventListener("click", () => this.scrollToTop());
    }

    // hidden is toggled off up front (JS-only feature: without JS the button
    // would otherwise sit there doing nothing) — .visible is the actual
    // show/hide switch, driven by scroll position.
    handleScroll() {
        this._button.classList.toggle("visible", window.scrollY > VISIBLE_AFTER_PX);
    }

    scrollToTop() {
        window.scrollTo({ top: 0, behavior: "smooth" });
    }
}

export default new ScrollToTop();
